class Solution {
    private int[] nums,multipliers;
    private Integer[][] memo;
    private int dfs(int step,int left){
        if(step==multipliers.length)return 0;
        if(memo[step][left]!=null)return memo[step][left];
        int right=nums.length-1-(step-left);
        int takeLeft=nums[left]*multipliers[step]+dfs(step+1,left+1);
        int takeRight=nums[right]*multipliers[step]+dfs(step+1,left);
        return memo[step][left]=Math.max(takeLeft,takeRight);
    }
    public int maximumScore(int[] nums,int[] multipliers){
        this.nums=nums;
        this.multipliers=multipliers;
        memo=new Integer[multipliers.length][multipliers.length];
        return dfs(0,0);
    }
}

code.kotlin:
class Solution {
    private lateinit var nums:IntArray;
    private lateinit var multipliers:IntArray;
    private lateinit var memo:Array<IntArray>;
    private fun dfs(step:Int,left:Int):Int{
        if(step==multipliers.size)return 0;
        if(memo[step][left]!=Int.MIN_VALUE)return memo[step][left];
        val right=nums.size-1-(step-left);
        memo[step][left]=maxOf(nums[left]*multipliers[step]+dfs(step+1,left+1),nums[right]*multipliers[step]+dfs(step+1,left));
        return memo[step][left]
    };
    fun maximumScore(nums:IntArray,multipliers:IntArray):Int{
        this.nums=nums;
        this.multipliers=multipliers;
        memo=Array(multipliers.size){
            IntArray(multipliers.size){
                Int.MIN_VALUE
            }
        };
        return dfs(0,0)
    }
}

